import{_ as i,l,o as e,c as s,v as t,p as d,x as o,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"配方与机台软件","description":"","frontmatter":{"title":"配方与机台软件","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-recipe-software.md","filePath":"litho/tool-recipe-software.md","lastUpdated":1789023840000}'),c={name:"litho/tool-recipe-software.md"};function _(E,a,A,f,m,u){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="配方与机台软件" tabindex="-1">配方与机台软件 <a class="header-anchor" href="#配方与机台软件" aria-label="Permalink to &quot;配方与机台软件&quot;">​</a></h1><div class="epigraph"><p>曝光机是一台会跑状态机的精密仪器。配方把照明、剂量、对准、扫描编成可重复的剧本；软件缺陷会表现为「随机套刻」。</p><footer>—— 对照 scanner recipe / job deck；APF 一类机台软件通识</footer></div><p><a href="/litho/tool-uptime-mtbf">上一课</a>把停机算进稼动。缺口是：很多停机和偏移来自配方与联机软件，不是轴承。本课钉配方软件，校准周期收束本单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一硬件，配方选错照明、选错对准标记、扫描向反了，CD 和套刻会整批废。版本：胶换了剂量表没升版。联机：轨道送来的片 ID 对不上 job。把所有偏移写成光学，会漏软件配置。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方版本进变更控制，与胶批、掩模 ID 绑定。仿真/干跑检查标记是否在窗、场图是否越界。日志：哪条校正表、哪次校准被用。与 APC 课分工：APC 改剂量套刻偏置，本课管机台是否执行了那张配方。</p>',7)),(e(),d(p,null,{default:o(()=>[h(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E9%85%8D%E6%96%B9%E7%89%88%E6%9C%AC%22%5D%20--%3E%20JOB%5B%22%E6%9C%AC%E6%89%B9%20job%22%5D%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%20ID%22%5D%20--%3E%20JOB%0A%20%20RES%5B%22%E8%83%B6%20%2F%20%E8%BD%A8%E9%81%93%22%5D%20--%3E%20JOB%0A%20%20JOB%20--%3E%20EXE%5B%22%E6%89%AB%E6%8F%8F%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>状态机：装载 → 预对准 → 对准 → 曝光 → 卸载。中断恢复若丢校正表，会留下一场「幽灵指纹」。时间同步：机台钟与计量钟差，APC 会喂错批。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课把硬件零点周期性拉回来：校准。配方再对，零点漂了仍偏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配方是可版本化的光学与运动剧本。</li><li>联机状态与日志是「随机」失效的第一现场。</li><li>出处：对准与 APC 课；SEMI 作业管理通识。</li></ul>',6))])}const C=i(c,[["render",_]]);export{B as __pageData,C as default};
